#include <iostream>
#include <string>
#include <algorithm>
#include <vector>

using namespace std;

int main() {
    int n;
    cin >> n;
    cin.ignore();  // Ignore the newline after the integer input

    while (n--) {
        string s;
        getline(cin, s);
        string ans;

        // Using a single pass transformation instead of nested loops
        for (int a = 0; a < 27 && ans.empty(); a++) {
            for (int b = 0; b < 27 && ans.empty(); b++) {
                // Prepare a transformed string in one go
                string tmp;
                tmp.reserve(s.size());  // Reserve space to avoid multiple allocations
                for (char c : s) {
                    if (isalpha(c)) {
                        tmp += (a * (c - 'a') + b) % 26 + 'a';  // Append directly to tmp
                    } else {
                        tmp += c;  // Preserve non-alphabetic characters
                    }
                }

                // Check if transformed string contains "this" or "that"
                if (tmp.find("this") != string::npos || tmp.find("that") != string::npos) {
                    ans = tmp;  // Store the first valid transformation
                }
            }
        }
        cout << ans << endl;
    }
}

